import yaml


def _values(path):
    with open(path) as fh:
        return yaml.safe_load(fh)


def test_runner_pools_exclude_small_node():
    for path in ('manifests/arc-api-arm64/values.yaml', 'manifests/arc-menu-deploy/values.yaml'):
        spec = _values(path)['template']['spec']
        terms = spec['affinity']['nodeAffinity']['requiredDuringSchedulingIgnoredDuringExecution']['nodeSelectorTerms']
        assert terms[0]['matchExpressions'][0]['values'] == ['node-small-01']
